#include "AccountsPageHsx.h"
#include "FormDialogHsx.h"
#include "PasswordHsx.h"
#include "ThemeHsx.h"
#include "UiHsx.h"
#include <QFrame>
#include <QLabel>
#include <QMessageBox>
#include <QTableWidget>
#include <QVBoxLayout>
namespace im {
using S=AppSessionHsx;
AccountsPageHsx::AccountsPageHsx(AppSessionHsx& s,QWidget* parent):QWidget(parent),session_(s){auto* layout=new QVBoxLayout(this);layout->setContentsMargins(0,0,0,0);layout->setSpacing(18);auto* profileCard=new QFrame;profileCard->setObjectName("card");auto* p=new QHBoxLayout(profileCard);p->setContentsMargins(24,24,24,24);auto* labels=new QVBoxLayout;name_=new QLabel;name_->setObjectName("sectionTitle");details_=new QLabel;details_->setObjectName("muted");labels->addWidget(name_);labels->addWidget(details_);p->addLayout(labels,1);UiHsx::button(p,"编辑个人资料",[this]{profile();});layout->addWidget(profileCard);
    auto* card=new QFrame;card->setObjectName("card");auto* c=new QVBoxLayout(card);c->setContentsMargins(22,22,22,20);c->setSpacing(14);auto* title=new QLabel("我的服务账号");title->setObjectName("sectionTitle");c->addWidget(title);auto* hint=new QLabel("开通微博后，从左下角服务切换进入独立微博空间。未开通微博的账号不会显示微博入口。");hint->setObjectName("muted");hint->setWordWrap(true);c->addWidget(hint);
    table_=UiHsx::table({"服务","服务号","昵称","QQ 关系","好友数量","当前"});table_->setObjectName("servicesTable");c->addWidget(table_,1);auto* actions=new QHBoxLayout;UiHsx::button(actions,"开通服务",[this]{open();},true);UiHsx::button(actions,"修改登录昵称 / 密码",[this]{edit();});UiHsx::button(actions,"绑定 QQ",[this]{bind();});UiHsx::button(actions,"关闭服务",[this]{closeService();});actions->addStretch();c->addLayout(actions);layout->addWidget(card,1);
}
void AccountsPageHsx::refresh(){if(!session_.signedIn())return;const auto& u=session_.data().user(session_.user());name_->setText(S::q(u.name()));details_->setText(QString("%1 · 出生 %2 · 注册 %3 · T龄 %4 年").arg(S::q(u.location())).arg(S::q(u.birth().str())).arg(S::q(u.applied().str())).arg(u.tAge()));table_->setRowCount(0);
    for(const auto& [type,a]:u.services())if(activeService(type))UiHsx::row(table_,{S::q(serviceName(type)),QString::number(a.number()),S::q(a.nick()),a.shared()?"与 QQ 共用账号":a.boundQQ()?QString("绑定 %1").arg(a.boundQQ()):"独立账号",QString::number(a.friends().size()),type==session_.service()?"使用中":""},static_cast<int>(type)+1);
}
void AccountsPageHsx::profile(){const auto& u=session_.data().user(session_.user());FormDialogHsx f("个人资料",this);f.text("name","登录昵称（全平台）",S::q(u.name()));f.text("location","地区",S::q(u.location()));f.submit([&](const FormDialogHsx& form){return session_.command("profile",{{"name",form.textValue("name").trimmed()},{"location",form.textValue("location")}},[&]{session_.accounts().profile(session_.user(),S::s(form.textValue("name")),S::s(form.textValue("location")));},"个人资料已更新");});f.exec();}
void AccountsPageHsx::open(){FormDialogHsx f("开通新服务",this);f.combo("service","服务",UiHsx::allServices());f.text("number","服务号",session_.data().user(session_.user()).services().count(ServiceHsx::QQ)?QString::number(session_.data().account(session_.user(),ServiceHsx::QQ).number()):QString{});f.text("nick","服务昵称",S::q(session_.data().user(session_.user()).name()));f.text("password","密码（至少 8 字节）",{},true);f.submit([&](const FormDialogHsx& form){return session_.command("account.open",{{"contact",form.choice("service")},{"number",form.textValue("number")},{"password",form.textValue("password")},{"shared",false}},[&]{bool ok=false;const auto number=form.textValue("number").toLongLong(&ok);require(ok,"服务号应为整数");PasswordHsx::check(S::s(form.textValue("password")));session_.accounts().open(session_.user(),static_cast<ServiceHsx>(form.choice("service")),number,S::s(form.textValue("nick")),S::s(form.textValue("password")),false);},"服务已开通");});f.exec();}
void AccountsPageHsx::edit(){const int index=static_cast<int>(UiHsx::selected(table_));if(!index)return;const auto type=static_cast<ServiceHsx>(index-1);FormDialogHsx f("修改登录昵称与密码",this);f.text("nick","登录昵称（全平台）",S::q(session_.data().user(session_.user()).name()));f.text("old","原密码",{},true);f.text("new","新密码（至少 8 字节，空白保留原密码）",{},true);f.text("repeat","再次输入新密码",{},true);f.submit([&](const FormDialogHsx& form){if(form.textValue("new")!=form.textValue("repeat")){QMessageBox::warning(&f,"密码不一致","两次新密码不一致");return false;}return session_.command("account.edit",{{"service",int(type)},{"nick",form.textValue("nick").trimmed()},{"old",form.textValue("old")},{"password",form.textValue("new")}},[&]{require(form.textValue("new")==form.textValue("repeat"),"两次新密码不一致");if(!form.textValue("new").isEmpty())PasswordHsx::check(S::s(form.textValue("new")));session_.accounts().edit(session_.user(),type,S::s(form.textValue("nick")),S::s(form.textValue("old")),S::s(form.textValue("new")));},"服务信息已更新");});f.exec();}
void AccountsPageHsx::closeService(){const int index=static_cast<int>(UiHsx::selected(table_));if(!index)return;const auto type=static_cast<ServiceHsx>(index-1);if(UiHsx::confirm(this,"关闭此服务？对应好友关系、入群关系和待处理申请将被清理。"))session_.command("account.close",{{"service",int(type)}},[&]{session_.accounts().close(session_.user(),type);},"服务已关闭");}
void AccountsPageHsx::bind(){FormDialogHsx f("微信绑定 QQ",this);f.text("qq","本人的 QQ 号",QString::number(session_.user()));f.submit([&](const FormDialogHsx& form){return session_.command("account.bind",{{"number",form.textValue("qq")}},[&]{bool ok=false;const auto number=form.textValue("qq").toLongLong(&ok);require(ok,"QQ号应为整数");session_.accounts().bind(session_.user(),number);},"微信已绑定 QQ");});f.exec();}
}
